function ReadableText({text=''}) {
 const lines=String(text||'').replace(/\r/g,'').split('\n');
 const nodes=[];
 for(let i=0;i<lines.length;i++){
  const raw=lines[i], line=raw.trim();
  if(!line){nodes.push(<div className="readable-gap" key={i}/>);continue;}
  if(line.startsWith('|')){
   const rows=[];
   while(i<lines.length && lines[i].trim().startsWith('|')){
    const cells=lines[i].trim().replace(/^\||\|$/g,'').split('|').map(x=>x.trim());
    if(!cells.every(x=>/^:?-{3,}:?$/.test(x)))rows.push(cells);
    i++;
   }
   i--;
   if(rows.length){const headers=rows[0];nodes.push(<div className="table-scroll" key={`table-${i}`}><table><thead><tr>{headers.map((c,j)=><th key={j}>{c}</th>)}</tr></thead><tbody>{rows.slice(1).map((r,ri)=><tr key={ri}>{headers.map((_,j)=><td key={j}>{r[j]||''}</td>)}</tr>)}</tbody></table></div>);}
   continue;
  }
  const heading=/^#{1,6}\s/.test(line), bullet=/^[-•*]\s/.test(line), numbered=/^\d+[.)]\s/.test(line);
  const clean=line.replace(/^#{1,6}\s*/,'').replace(/^\*\s+/,'').replace(/^\d+[.)]\s*/,'').replace(/\*\*/g,'').replace(/`/g,'').replace(/^[-•]\s*/,'');
  if(heading)nodes.push(<h3 key={i}>{clean}</h3>);
  else if(bullet)nodes.push(<div className="readable-bullet" key={i}><span>•</span>{clean}</div>);
  else if(numbered)nodes.push(<div className="readable-number" key={i}>{clean}</div>);
  else nodes.push(<p key={i}>{clean}</p>);
 }
 return <div className="readable-output">{nodes}</div>;
}

function QuizView({text=''}) {
 const blocks=String(text).split(/(?=^\s*(?:Q:|Question\s*\d*[:.]))/im).filter(x=>/(?:Q:|Question\s*\d*[:.])/i.test(x));
 const [answers,setAnswers]=useState({});
 if(!blocks.length)return <ReadableText text={text}/>;
 const questions=blocks.map((b,i)=>{const lines=b.split('\n').map(x=>x.trim()).filter(Boolean);const q=(lines.find(x=>/^(Q:|Question)/i.test(x))||'').replace(/^(Q:|Question\s*\d*[:.]?)\s*/i,'');const opts=lines.filter(x=>/^[A-D][).]\s*/.test(x)).map(x=>({key:x[0].toUpperCase(),value:x.slice(2).trim()}));const correct=(lines.find(x=>/^(Correct|Answer)\s*:/i.test(x))||'').split(':').slice(1).join(':').trim().replace(/[^A-D]/ig,'').toUpperCase().slice(0,1);const explanation=(lines.find(x=>/^Explanation\s*:/i.test(x))||'').replace(/^Explanation\s*:/i,'').trim();return {q,opts,correct,explanation,id:i};});
 return <div className="quiz-cards">{questions.map((q,i)=><section className="quiz-question" key={i}><b>{i+1}. {q.q}</b><div className="quiz-options">{q.opts.map(o=><button className={'quiz-option '+(answers[i]===o.key?'selected':'')+(answers[i]&&q.correct===o.key?' right':'')+(answers[i]===o.key&&q.correct&&answers[i]!==q.correct?' wrong':'')} onClick={()=>setAnswers(v=>({...v,[i]:o.key}))}>{o.key}. {o.value}</button>)}</div>{answers[i]&&<div className="quiz-feedback">{q.correct?(answers[i]===q.correct?'Correct answer':'Correct answer: '+q.correct):'Answer selected'}{q.explanation&&<p>{q.explanation}</p>}</div>}</section>)}</div>;
}
function FlashcardView({text=''}) {
 const blocks=String(text).split(/(?=^\s*(?:Q:|Question\s*\d*[:.]))/im).filter(x=>/(?:Q:|Question\s*\d*[:.])/i.test(x));
 const [index,setIndex]=useState(0),[flipped,setFlipped]=useState(false);
 const cards=blocks.map(b=>{const lines=b.split('\n').map(x=>x.trim()).filter(Boolean);return {q:(lines.find(x=>/^(Q:|Question)/i.test(x))||'').replace(/^(Q:|Question\s*\d*[:.]?)\s*/i,''),a:(lines.find(x=>/^(A:|Answer)/i.test(x))||'').replace(/^(A:|Answer)\s*[:.]?\s*/i,'')};}).filter(x=>x.q&&x.a);
 if(!cards.length)return <ReadableText text={text}/>;
 return <div className="flashcard-stage"><button className="flashcard-face" onClick={()=>setFlipped(v=>!v)}><small>{flipped?'ANSWER':'QUESTION'} · CLICK TO FLIP</small><b>{flipped?cards[index].a:cards[index].q}</b></button><div className="action-row"><button className="btn ghost" disabled={index===0} onClick={()=>{setIndex(v=>v-1);setFlipped(false)}}>Previous</button><span>{index+1} / {cards.length}</span><button className="btn" disabled={index===cards.length-1} onClick={()=>{setIndex(v=>v+1);setFlipped(false)}}>Next</button></div></div>;
}
function MindMapView({text=''}) {
 const clean = value => String(value||'').replace(/^\s*(?:[-*•]|\d+[.)])\s*/, '').replace(/^#{1,6}\s*/, '').replace(/\*\*/g,'').replace(/`/g,'').replace(/[：:]$/,'').trim();
 const rawLines=String(text||'').split(/\r?\n/).filter(line=>line.trim() && !/^\s*\|?\s*:?-{3,}/.test(line) && !/^\s*\|/.test(line));
 if(!rawLines.length)return <div className="empty">Generate a mind map from a selected document.</div>;
 const title=clean(rawLines[0])||'Your Notes';
 const branches=[]; let current=null; let lastIndent=0;
 for(const raw of rawLines.slice(1)){
  const value=clean(raw); if(!value)continue;
  const indent=(raw.match(/^\s*/)||[''])[0].length;
  const heading=/^\s*#{1,3}\s|^\s*\*\*[^*]+\*\*/.test(raw);
  const numbered=/^\s*\d+[.)]\s/.test(raw);
  const bullet=/^\s*[-*•]\s/.test(raw);
  if(heading || (numbered && indent===0) || !current){
   current={title:value,children:[]}; branches.push(current); lastIndent=indent;
  } else if(bullet || indent>lastIndent || current.children.length===0){
   current.children.push(value);
  } else {
   current={title:value,children:[]}; branches.push(current); lastIndent=indent;
  }
 }
 if(!branches.length)branches.push({title:'Key ideas',children:rawLines.slice(1).map(clean).filter(Boolean)});
 return <div className="mindmap-canvas mindmap-hierarchical" aria-label={`Hierarchical mind map for ${title}`}>
  <div className="mindmap-center"><span>MAIN TOPIC</span>{title}</div>
  <div className="mindmap-root-connector" aria-hidden="true"/>
  <div className="mindmap-tree-grid">
   {branches.slice(0,12).map((branch,index)=><section className="mindmap-branch" key={index}>
    <div className="mindmap-branch-title"><span>BRANCH {index+1}</span>{branch.title}</div>
    {branch.children?.length>0&&<div className="mindmap-children">{branch.children.slice(0,12).map((child,j)=><div className="mindmap-subbranch" key={j}><div className="mindmap-child">{child}</div></div>)}</div>}
   </section>)}
  </div>
 </div>;
}

