 const studyDocumentSelect=<label className="study-document-select">Select uploaded notes<select value={selected?.id??''} onChange={e=>chooseStudyDoc(e.target.value)}><option value="">{docs.length?'Choose a document':'No uploaded notes yet'}</option>{docs.map(d=><option key={d.id} value={d.id}>{d.name||d.title}</option>)}</select>{!docs.length&&<small>Upload a document first. The selected notes will be used for this study tool.</small>}</label>;
 const deleteDoc=async d=>{
  if(!token||!Number.isInteger(Number(d?.id)))return notify('Only saved documents can be deleted. Sign in first.');
  const title=d.title||d.name||'this document';
  if(!window.confirm(`Permanently delete "${title}" and all its uploaded pages? This cannot be undone.`))return;
  setBusy(true);
  try{
   await api(`/api/documents/${d.id}`,{method:'DELETE'});
   let workspaceMap={};try{workspaceMap=JSON.parse(localStorage.getItem('ln-document-workspaces')||'{}')}catch{}delete workspaceMap[String(d.id)];localStorage.setItem('ln-document-workspaces',JSON.stringify(workspaceMap));
   if(String(selected?.id)===String(d.id)){setSelected(null);setSource('');setAnswer('');setPageIndex(0);}
   await refreshDocs();
   notify('Document and its uploaded pages deleted.');
   if(String(selected?.id)===String(d.id))go('My Documents');
  }catch(e){notify(`Could not delete document: ${e.message}`)}
  finally{setBusy(false)}
 };
